// Même syntaxe que site/api/lib/Modeles.php : {{x}}, {{#x}}…{{/x}}, {{^x}}…{{/x}}.
function rendre(g, v) {
  const re = /\{\{([#^])([a-z0-9_]+)\}\}((?:(?!\{\{[#^]\2\}\})[\s\S])*?)\{\{\/\2\}\}/;
  for (let i = 0; i < 20 && re.test(g); i++) {
    g = g.replace(new RegExp(re.source, 'g'), (m, t, k, c) => ((t === '#') === !!v[k] ? c : ''));
  }
  return g.replace(/\{\{([a-z0-9_]+)\}\}/g, (m, k) => (v[k] === undefined || v[k] === null ? '' : String(v[k])));
}
function message(id, v) {
  const m = MODELES[id];
  return { sujet: rendre(m.sujet, v), texte: rendre(m.corps, v).trim() + '\n' };
}
// Version HTML sobre (paragraphes, liens complets), sans image ni pixel de suivi.
function versHtml(t) {
  const e = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  const lien = (s) => e(s).replace(/https?:\/\/[^\s<]+/g, (u) => '<a href="' + u + '" style="color:#1D1F22">' + u + '</a>');
  return '<div style="max-width:600px;font-family:Arial,sans-serif;font-size:17px;line-height:1.55;color:#1D1F22">'
    + t.trim().split(/\n{2,}/).map((b) => b.startsWith('--\n')
      ? '<hr style="border:0;border-top:1px solid #D9DBDE"><p style="font-size:14px;color:#44494F">' + b.slice(3).split('\n').map(lien).join('<br>') + '</p>'
      : '<p>' + b.split('\n').map(lien).join('<br>') + '</p>').join('') + '</div>';
}
